using System.IO.Compression;
using System.Text;
class ZipCreator
{
    void CreateArchive()
    {
        // .NET 9 now sets the UTF-8 flag on ZipArchiveEntry names by default.
        // The legacy Java consumer expects Shift-JIS, so we must specify the
        // encoding explicitly to suppress the UTF-8 flag.
        using var archive = ZipFile.Open("data.zip", ZipArchiveMode.Create, Encoding.GetEncoding("shift_jis"));
        archive.CreateEntry("レポート/月次.csv");  // Japanese path
        archive.CreateEntry("données/résumé.txt"); // French accented
    }
}

